def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    r = [(p.get(a.get('element')) or {}).get('covalent_radius_A') for a in sites]
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    nearest = [inf for a in sites]
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and d > 1e-8 and occ[j] > 0:
            if r[i] is not None and r[j] is not None and r[i] > 0 and r[j] > 0:
                nearest[i] = min(nearest[i], d / (r[i] + r[j]))
    total = 0.0
    weight = 0.0
    for i in range(n):
        if isfinite(nearest[i]) and occ[i] > 0:
            total += occ[i] * nearest[i]
            weight += occ[i]
    return total / weight if weight > 0 else 0.0

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    p = s.get('element_properties') or {}
    charges = []
    occ = [max(a.get('occupancy', 1.0) or 0.0, 0.0) for a in sites]
    for site in sites:
        a = p.get(site.get('element')) or {}
        g = a.get('group')
        en = a.get('eneg')
        v = a.get('valence_electrons')
        row = a.get('row')
        q = None
        if g == 1 or g == 2:
            q = float(g)
        elif g == 13:
            q = 3.0
        elif g == 14:
            q = -4.0 if en is not None and en >= 2.3 else 4.0
        elif g is not None and 15 <= g <= 17:
            q = float(g - 18)
        elif g == 18:
            q = 0.0
        elif v is not None and ((g is not None and 3 <= g <= 12) or (g is None and row is not None and row >= 6)):
            q = min(max(v, 0.0), 3.0)
        charges += [q]
    weight = sum(occ[i] for i in range(n) if charges[i] is not None)
    if weight <= 0:
        return 0.0
    total = 0.0
    for b in s.get('neighbors') or []:
        i = b.get('i', -1)
        j = b.get('j', -1)
        d = b.get('distance_A') or 0.0
        if 0 <= i < n and 0 <= j < n and 1e-8 < d < 6.0:
            if charges[i] is not None and charges[j] is not None:
                kernel = exp(-d / 2.0) * (1.0 / max(d, 0.5) - 1.0 / 6.0)
                total += occ[i] * occ[j] * charges[i] * charges[j] * kernel
    return total / (2.0 * weight)
